// Opponent brain. Pure data in / input out, so it can be unit tested.
import { ARENA, clamp, forwardSpeed, predictBall, wrapAngle } from './physics.mjs';

export const DIFFICULTIES = {
  rookie: {
    label: 'Rookie',
    reaction: 0.3,
    aimError: 0.2,
    jumpSkill: 0.35,
    boostSkill: 0.45,
    lookahead: 0.25,
    throttle: 0.86,
  },
  pro: {
    label: 'Pro',
    reaction: 0.15,
    aimError: 0.09,
    jumpSkill: 0.78,
    boostSkill: 0.82,
    lookahead: 0.42,
    throttle: 1,
  },
  allstar: {
    label: 'All-Star',
    reaction: 0.07,
    aimError: 0.035,
    jumpSkill: 1,
    boostSkill: 1,
    lookahead: 0.6,
    throttle: 1,
  },
};

export function createBot(difficulty = 'pro', seed = 1) {
  return {
    difficulty,
    config: DIFFICULTIES[difficulty] || DIFFICULTIES.pro,
    think: 0,
    target: { x: 0, z: 0 },
    aim: { x: -1, z: 0 },
    mode: 'attack',
    jumpCooldown: 0,
    jumpLock: 0,
    spread: 0,
    seed,
    rng: mulberry32(seed),
    lastBoost: false,
    padTarget: null,
  };
}

function mulberry32(a) {
  return function random() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * state: { self, ball, opponent, pads, time }
 * The bot defends +x and attacks -x.
 */
export function updateBot(bot, state, dt) {
  const { self, ball, opponent } = state;
  const cfg = bot.config;
  bot.jumpCooldown = Math.max(0, bot.jumpCooldown - dt);
  bot.think -= dt;
  bot.spread += dt;

  const distToBall = Math.hypot(ball.pos.x - self.pos.x, ball.pos.z - self.pos.z);
  const ballSpeed = Math.hypot(ball.vel.x, ball.vel.z);
  const ballThreat =
    ball.pos.x > 12 && Math.hypot(ball.pos.x - 42, ball.pos.z) < 30 ? 1 : 0;

  // Re-plan on a human-ish cadence.
  if (bot.think <= 0) {
    bot.think = cfg.reaction * (0.75 + bot.rng() * 0.55);
    const horizon = clamp(distToBall / 34, 0.06, cfg.lookahead) * (0.7 + bot.rng() * 0.5);
    const predicted = predictBall(ball, horizon);

    // Attack the player's goal, aiming away from its edges.
    const goalZ = (bot.rng() - 0.5) * 7;
    let aimX = -ARENA.halfLength - predicted.x;
    let aimZ = goalZ - predicted.z;
    const aimLen = Math.hypot(aimX, aimZ) || 1;
    aimX /= aimLen;
    aimZ /= aimLen;
    // Rotate the aim a little based on skill + noise.
    const wobble = (bot.rng() - 0.5) * 2 * cfg.aimError;
    const cos = Math.cos(wobble);
    const sin = Math.sin(wobble);
    bot.aim.x = aimX * cos - aimZ * sin;
    bot.aim.z = aimX * sin + aimZ * cos;

    const carToBallX = self.pos.x - predicted.x;
    const carToBallZ = self.pos.z - predicted.z;
    const wrongSide = carToBallX * bot.aim.x + carToBallZ * bot.aim.z > 1.6;

    // Stand between the ball and our own goal when it is threatening.
    if (ballThreat && ball.pos.x > 24) {
      bot.mode = 'defend';
      const gx = 42 - ball.pos.x;
      const gz = -ball.pos.z;
      const gl = Math.hypot(gx, gz) || 1;
      bot.target.x = predicted.x + (gx / gl) * 3.6;
      bot.target.z = predicted.z + (gz / gl) * 3.6;
    } else if (wrongSide && distToBall < 15) {
      // Loop around the ball instead of driving through it.
      bot.mode = 'loop';
      const perp = self.pos.z >= predicted.z ? 1 : -1;
      bot.target.x = predicted.x + bot.aim.x * 4.4 + -bot.aim.z * perp * 7.5;
      bot.target.z = predicted.z + bot.aim.z * 4.4 + bot.aim.x * perp * 7.5;
    } else if (predicted.y > 5.5 && distToBall < 13) {
      // Wait under the dropping ball, then challenge.
      bot.mode = 'aerial';
      bot.target.x = predicted.x - bot.aim.x * 2.4;
      bot.target.z = predicted.z - bot.aim.z * 2.4;
    } else {
      bot.mode = 'attack';
      bot.target.x = predicted.x - bot.aim.x * 2.7;
      bot.target.z = predicted.z - bot.aim.z * 2.7;
    }

    // Fall back toward midfield when the ball is far upfield and we have no boost.
    if (bot.mode === 'attack' && ball.pos.x < -6 && ballSpeed < 5 && self.boost < 15) {
      const big = (state.pads || [])
        .filter((p) => p.active && p.big)
        .sort(
          (a, b) =>
            Math.hypot(a.x - self.pos.x, a.z - self.pos.z) -
            Math.hypot(b.x - self.pos.x, b.z - self.pos.z),
        )[0];
      if (big) {
        bot.padTarget = big;
        bot.mode = 'boost';
        bot.target.x = big.x;
        bot.target.z = big.z;
      }
    }
  }

  const target = bot.padTarget && bot.mode === 'boost' ? bot.padTarget : bot.target;

  // Steering.
  const dx = target.x - self.pos.x;
  const dz = target.z - self.pos.z;
  const targetDist = Math.hypot(dx, dz);
  const desiredYaw = Math.atan2(dx, dz);
  const diff = wrapAngle(desiredYaw - self.yaw);
  let steer = clamp(diff * 2.35, -1, 1);

  // Throttle: brake into sharp turns, then commit.
  let throttle = cfg.throttle;
  const speed = Math.hypot(self.vel.x, self.vel.z);
  if (Math.abs(diff) > 1.75 && speed > 10) throttle = -0.5;
  else if (Math.abs(diff) > 1.15 && speed > 17) throttle = 0.1;
  if (targetDist < 1.6 && Math.abs(diff) > 2.2) throttle = 0.35;

  const towardTarget = diff > -1.05 && diff < 1.05;
  let boost = false;
  if (self.boost > 3 && towardTarget && ballSpeed < 40) {
    const passingBall = distToBall < 5 && forwardSpeed(self) > 8;
    if (bot.mode === 'boost' || passingBall || targetDist > 9) {
      boost = bot.rng() < cfg.boostSkill ? true : bot.lastBoost;
    }
  }
  if (bot.mode === 'defend' && ballThreat) boost = self.boost > 3 && towardTarget;
  bot.lastBoost = boost;

  // Jumping and flipping at the ball.
  let jumpPressed = false;
  const ballAbove = ball.pos.y > 2.5;
  const ballClose = distToBall < 7;
  if (self.onGround && ballAbove && ballClose && bot.jumpCooldown <= 0) {
    if (bot.rng() < cfg.jumpSkill * 0.9) {
      jumpPressed = true;
      bot.jumpCooldown = 0.55;
      bot.jumpLock = 0.18;
    }
  } else if (!self.onGround && self.jumps === 1 && bot.jumpLock > 0) {
    bot.jumpLock -= dt;
    if (bot.jumpLock <= 0 && distToBall < 5.5) {
      jumpPressed = true;
      bot.jumpCooldown = 0.5;
    }
  }

  // Keep the bot inside the arena target zone.
  void opponent;

  return { throttle, steer, boost, jumpPressed };
}

import * as THREE from 'three';

const MAX = 1400;

/** A compact CPU particle pool rendered as soft additive points. */
export class ParticlePool {
  constructor(scene) {
    this.max = MAX;
    this.cursor = 0;
    this.positions = new Float32Array(MAX * 3);
    this.colors = new Float32Array(MAX * 3);
    this.sizes = new Float32Array(MAX);
    this.alphas = new Float32Array(MAX);
    this.vel = new Float32Array(MAX * 3);
    this.life = new Float32Array(MAX);
    this.maxLife = new Float32Array(MAX);
    this.size0 = new Float32Array(MAX);
    this.gravity = new Float32Array(MAX);
    this.drag = new Float32Array(MAX);
    this.baseColor = new Float32Array(MAX * 3);

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    geo.setAttribute('particleColor', new THREE.BufferAttribute(this.colors, 3));
    geo.setAttribute('size', new THREE.BufferAttribute(this.sizes, 1));
    geo.setAttribute('alpha', new THREE.BufferAttribute(this.alphas, 1));
    geo.setDrawRange(0, MAX);

    const mat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: {},
      vertexShader: /* glsl */ `
        attribute vec3 particleColor;
        attribute float size;
        attribute float alpha;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = particleColor;
          vAlpha = alpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = size * (310.0 / max(1.0, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: /* glsl */ `
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec2 p = gl_PointCoord - vec2(0.5);
          float d = length(p) * 2.0;
          if (d > 1.0) discard;
          float core = pow(1.0 - d, 1.7);
          gl_FragColor = vec4(vColor * core, core * vAlpha);
        }
      `,
    });

    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
    this.geo = geo;
  }

  emit({
    x = 0,
    y = 0,
    z = 0,
    vx = 0,
    vy = 0,
    vz = 0,
    spread = 1,
    color = [1, 1, 1],
    size = 0.6,
    life = 0.6,
    gravity = 0,
    drag = 1.4,
    count = 1,
  } = {}) {
    for (let n = 0; n < count; n++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % MAX;
      const i3 = i * 3;
      this.positions[i3] = x + (Math.random() - 0.5) * spread;
      this.positions[i3 + 1] = y + (Math.random() - 0.5) * spread;
      this.positions[i3 + 2] = z + (Math.random() - 0.5) * spread;
      this.vel[i3] = vx + (Math.random() - 0.5) * spread * 3;
      this.vel[i3 + 1] = vy + (Math.random() - 0.5) * spread * 3;
      this.vel[i3 + 2] = vz + (Math.random() - 0.5) * spread * 3;
      const tint = 0.82 + Math.random() * 0.35;
      this.baseColor[i3] = color[0] * tint;
      this.baseColor[i3 + 1] = color[1] * tint;
      this.baseColor[i3 + 2] = color[2] * tint;
      this.colors[i3] = this.baseColor[i3];
      this.colors[i3 + 1] = this.baseColor[i3 + 1];
      this.colors[i3 + 2] = this.baseColor[i3 + 2];
      this.life[i] = life * (0.75 + Math.random() * 0.5);
      this.maxLife[i] = this.life[i];
      this.size0[i] = size * (0.7 + Math.random() * 0.7);
      this.sizes[i] = this.size0[i];
      this.alphas[i] = 1;
      this.gravity[i] = gravity;
      this.drag[i] = drag;
    }
  }

  update(dt) {
    for (let i = 0; i < MAX; i++) {
      if (this.life[i] <= 0) {
        this.alphas[i] = 0;
        continue;
      }
      const i3 = i * 3;
      this.life[i] -= dt;
      if (this.life[i] <= 0) {
        this.alphas[i] = 0;
        continue;
      }
      this.vel[i3 + 1] -= this.gravity[i] * dt;
      const d = Math.exp(-this.drag[i] * dt);
      this.vel[i3] *= d;
      this.vel[i3 + 1] *= d;
      this.vel[i3 + 2] *= d;
      this.positions[i3] += this.vel[i3] * dt;
      this.positions[i3 + 1] += this.vel[i3 + 1] * dt;
      this.positions[i3 + 2] += this.vel[i3 + 2] * dt;
      if (this.positions[i3 + 1] < 0.1) {
        this.positions[i3 + 1] = 0.1;
        this.vel[i3 + 1] *= -0.25;
      }
      const t = this.life[i] / this.maxLife[i];
      this.alphas[i] = t * t;
      this.sizes[i] = this.size0[i] * (0.55 + t * 0.65);
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.particleColor.needsUpdate = true;
    this.geo.attributes.size.needsUpdate = true;
    this.geo.attributes.alpha.needsUpdate = true;
  }
}

/** Tiny synthesized sound engine - no audio files needed. */
export class SoundLab {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.ready = false;
    this.engine = null;
    this.boostGain = null;
    this.crowdGain = null;
    this.master = null;
    this.lastHit = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
    } catch {
      return;
    }
    const ctx = this.ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.9;
    this.master.connect(ctx.destination);

    // Reusable noise buffer.
    const seconds = 2;
    this.noise = ctx.createBuffer(1, ctx.sampleRate * seconds, ctx.sampleRate);
    const data = this.noise.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;

    // Crowd bed.
    const crowd = ctx.createBufferSource();
    crowd.buffer = this.noise;
    crowd.loop = true;
    const crowdFilter = ctx.createBiquadFilter();
    crowdFilter.type = 'lowpass';
    crowdFilter.frequency.value = 480;
    crowdFilter.Q.value = 0.4;
    this.crowdGain = ctx.createGain();
    this.crowdGain.gain.value = 0.028;
    crowd.connect(crowdFilter).connect(this.crowdGain).connect(this.master);
    crowd.start();

    // Engine.
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.value = 48;
    const osc2 = ctx.createOscillator();
    osc2.type = 'triangle';
    osc2.frequency.value = 96;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 460;
    filter.Q.value = 2.4;
    const gain = ctx.createGain();
    gain.gain.value = 0.0;
    osc.connect(filter);
    osc2.connect(filter);
    filter.connect(gain).connect(this.master);
    osc.start();
    osc2.start();
    this.engine = { osc, osc2, filter, gain };

    // Boost jet.
    const boost = ctx.createBufferSource();
    boost.buffer = this.noise;
    boost.loop = true;
    const boostFilter = ctx.createBiquadFilter();
    boostFilter.type = 'bandpass';
    boostFilter.frequency.value = 950;
    boostFilter.Q.value = 0.7;
    this.boostGain = ctx.createGain();
    this.boostGain.gain.value = 0;
    boost.connect(boostFilter).connect(this.boostGain).connect(this.master);
    boost.start();
    this.ready = true;
  }

  resume() {
    this.init();
    if (this.ctx?.state === 'suspended') this.ctx.resume().catch(() => {});
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.9, this.ctx.currentTime, 0.05);
  }

  update(speed, boosting, throttle) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const norm = Math.min(1, speed / 38);
    this.engine.osc.frequency.setTargetAtTime(46 + norm * 92, t, 0.08);
    this.engine.osc2.frequency.setTargetAtTime(92 + norm * 185, t, 0.08);
    this.engine.filter.frequency.setTargetAtTime(380 + norm * 900, t, 0.1);
    const target = 0.012 + Math.abs(throttle) * 0.02 + norm * 0.035;
    this.engine.gain.gain.setTargetAtTime(target, t, 0.09);
    this.boostGain.gain.setTargetAtTime(boosting ? 0.11 : 0.0, t, boosting ? 0.04 : 0.14);
  }

  burst({ freq = 400, q = 1, duration = 0.2, gain = 0.2, type = 'bandpass', sweep = 0 }) {
    if (!this.ready || this.muted) return;
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, ctx.currentTime);
    if (sweep) filter.frequency.exponentialRampToValueAtTime(Math.max(40, freq + sweep), ctx.currentTime + duration);
    filter.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);
    src.connect(filter).connect(g).connect(this.master);
    src.start(ctx.currentTime, Math.random() * 1.5);
    src.stop(ctx.currentTime + duration + 0.02);
  }

  tone(freq, duration = 0.18, gain = 0.12, type = 'sine', slide = 0, delay = 0) {
    if (!this.ready || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + duration);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    osc.connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + duration + 0.03);
  }

  hit(strength = 0.5) {
    const now = performance.now();
    if (now - this.lastHit < 45) return;
    this.lastHit = now;
    this.burst({ freq: 160 + strength * 240, q: 1.2, duration: 0.16, gain: 0.12 + strength * 0.17, sweep: -90 });
    this.tone(92, 0.13, 0.08 + strength * 0.12, 'sine', -40);
  }

  bounce(strength = 0.5) {
    this.tone(150 + strength * 90, 0.1, 0.035 + strength * 0.04, 'triangle', -50);
  }

  jump() {
    this.burst({ freq: 520, q: 0.6, duration: 0.16, gain: 0.06, type: 'bandpass', sweep: 400 });
  }

  flip() {
    this.burst({ freq: 900, q: 0.7, duration: 0.2, gain: 0.09, sweep: 900 });
    this.tone(220, 0.14, 0.06, 'sawtooth', 110);
  }

  pad(big = false) {
    this.tone(big ? 520 : 780, 0.16, 0.06, 'sine', 380);
    this.tone(big ? 780 : 1040, 0.2, 0.04, 'sine', 520, 0.03);
  }

  beep(high = false) {
    this.tone(high ? 880 : 440, high ? 0.26 : 0.12, 0.1, 'square');
  }

  goal(blue = true) {
    if (!this.ready || this.muted) return;
    const root = blue ? 220 : 174.6;
    [0, 4, 7, 12].forEach((semi, i) => {
      this.tone(root * Math.pow(2, semi / 12), 0.7, 0.06, 'sawtooth', 0, i * 0.07);
    });
    this.burst({ freq: 700, q: 0.5, duration: 1.2, gain: 0.14, type: 'lowpass', sweep: 500 });
    this.crowdGain.gain.cancelScheduledValues(this.ctx.currentTime);
    this.crowdGain.gain.setValueAtTime(0.03, this.ctx.currentTime);
    this.crowdGain.gain.linearRampToValueAtTime(0.2, this.ctx.currentTime + 0.18);
    this.crowdGain.gain.linearRampToValueAtTime(0.028, this.ctx.currentTime + 2.6);
  }

  win(blue = true) {
    if (!this.ready || this.muted) return;
    const root = blue ? 261.6 : 196;
    [0, 5, 9, 12, 7, 12].forEach((semi, i) => {
      this.tone(root * Math.pow(2, semi / 12), 0.6, 0.07, 'triangle', 0, i * 0.12);
    });
    this.crowdGain.gain.setValueAtTime(0.04, this.ctx.currentTime);
    this.crowdGain.gain.linearRampToValueAtTime(0.18, this.ctx.currentTime + 0.3);
  }

  ui() {
    this.tone(620, 0.07, 0.045, 'sine', 180);
  }
}

