import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'))
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
page.on('pageerror', e => console.log('pageerror', e.message))
await page.goto('http://127.0.0.1:3002', { waitUntil: 'load', timeout: 45000 })
await page.waitForFunction(() => document.fonts.status === 'loaded')

const info = await page.evaluate(() => {
  const els = [...document.querySelectorAll('button, input[type="button"], input[type="submit"], [role="button"]')]
  return els.map(el => {
    const r = el.getBoundingClientRect()
    const cs = getComputedStyle(el)
    return {
      id: el.id, cls: el.className, text: (el.textContent||'').trim().slice(0,20),
      aria: el.getAttribute('aria-label'),
      visible: !!(r.width && r.height) && cs.visibility !== 'hidden' && cs.display !== 'none',
      rect: { x: r.x, y: r.y, w: r.width, h: r.height },
      hover: el.matches(':hover'), pe: cs.pointerEvents,
    }
  })
})
console.log(JSON.stringify(info, null, 1))

const rects = []
for (let i = 0; i < 6; i++) {
  rects.push(await page.evaluate(() => {
    const r = document.querySelector('#playBtn').getBoundingClientRect()
    const els = document.elementsFromPoint(r.x + r.width/2, r.y + r.height/2).map(e => e.id || e.className || e.tagName)
    return { rect: { x: r.x, y: r.y, w: r.width, h: r.height }, stack: els }
  }))
  await page.waitForTimeout(80)
}
console.log('rects', JSON.stringify(rects, null, 1))

const btn = page.locator('#playBtn')
try {
  await btn.click({ trial: true, timeout: 2000 })
  console.log('trial OK')
} catch (e) {
  console.log('trial FAIL', e.name, e.message.split('\n').slice(0,12).join('\n'))
}
try {
  await btn.click({ trial: true, timeout: 4000 })
  console.log('trial4 OK')
} catch (e) {
  console.log('trial4 FAIL', e.name, e.message.split('\n').slice(0,12).join('\n'))
}
console.log('phase', await page.evaluate(() => window.__rocket?.snapshot().phase))
await browser.close()

