let previous = performance.now();
let firstFrame = true;

function frame(now) {
  const rawDt = Math.min(0.05, Math.max(0, (now - previous) / 1000));
  previous = now;

  if (!state.paused) {
    if (state.phase === 'menu') {
      updateMenu(rawDt);
    } else if (state.phase === 'countdown') {
      updateCountdown(rawDt);
      state.slowmo = 1;
    } else if (state.phase === 'playing') {
      updatePlaying(rawDt);
    } else if (state.phase === 'goal') {
      updateGoal(rawDt);
    } else if (state.phase === 'gameover') {
      updateGameOver(rawDt);
    }

    world.update(rawDt, { boostActive: state.blue.boosting });
    world.updatePadScales(rawDt);
    updateEffects(rawDt);
    particles.update(rawDt);
    syncVisuals(rawDt);
    updateCamera(rawDt);
    updateHud();
  }

  renderer.render(scene, camera);

  if (firstFrame) {
    firstFrame = false;
    const loading = $('#loading');
    loading.classList.add('done');
    setTimeout(() => loading.remove(), 700);
  }
  requestAnimationFrame(frame);
}

