  const before = { calls: renderer.info.render.calls, triangles: renderer.info.render.triangles, pixelRatio: renderer.getPixelRatio(), size: { w: canvas.width, h: canvas.height }, lights, meshes, points, sprites }
  const t1 = time(), t2 = time()
  // hide all point lights
  scene.traverse(o => { if (o.isPointLight) o.visible = false })
  const t3 = time(), t4 = time()
  scene.traverse(o => { if (o.isPointLight) o.visible = true })
  // hide shadows already off; hide everything except floor? test empty render
