const cdp = await page.context().newCDPSession(page)
await cdp.send('Profiler.enable')
await cdp.send('Profiler.setSamplingInterval', { interval: 1000 })
await cdp.send('Profiler.start')
const t0 = Date.now()
await page.goto('http://127.0.0.1:3002', { waitUntil: 'load', timeout: 45000 })
await page.waitForFunction(() => document.fonts.status === 'loaded')
console.log('ready after', Date.now() - t0)
const { profile } = await cdp.send('Profiler.stop')
const byId = new Map(profile.nodes.map(n => [n.id, n]))
const self = new Map()
const dt = profile.timeDeltas
for (let i = 0; i < profile.samples.length; i++) {
  const n = byId.get(profile.samples[i]); if (!n) continue
  const cf = n.callFrame
  const key = `${cf.functionName || '(anon)'} ${cf.url.split('/').pop()}:${cf.lineNumber}`
  self.set(key, (self.get(key) || 0) + (dt[i] || 0))
}
const sorted = [...self.entries()].sort((a,b) => b[1]-a[1]).slice(0, 25)
const total = [...self.values()].reduce((a,b)=>a+b,0)
for (const [k,v] of sorted) console.log((v/1000).toFixed(0)+'ms', (v/total*100).toFixed(1)+'%', k)
await browser.close()

