page.setDefaultTimeout(30000)
await page.goto('http://127.0.0.1:3002', { waitUntil: 'load', timeout: 45000 })
await page.locator('body').waitFor({ state: 'visible' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
console.log('fonts ready; warming class =', await page.evaluate(() => document.body.className))
const cand = page.locator('button, input[type="button"], input[type="submit"], [role="button"]')
const deadline = Date.now() + 3000
let matches = []
do {
  matches = []
  for (const control of await cand.all()) {
    if (!await control.isVisible() || !await control.isEnabled()) continue
    const eligible = await control.evaluate((el) => {
      if (el.closest('a[href], form') || el.getAttribute('aria-disabled') === 'true') return false
      const label = el.getAttribute('aria-label') || el.value || el.textContent || ''
      return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim())
    })
    if (eligible) matches.push(control)
  }
  if (matches.length) break
  if (Date.now() >= deadline) break
  await page.waitForTimeout(200)
} while (Date.now() <= deadline)
console.log('matches', matches.length, 'at', Date.now() - (deadline - 3000), 'ms; warming =', await page.evaluate(() => document.body.className))
